/// Decides which clipboard changes must not be recorded.
public enum ClipboardFilter {
    /// Markers apps put on the pasteboard to say "do not keep this":
    /// passwords, one-time codes, and other generated or temporary data.
    /// See nspasteboard.org.
    public static let ignoredTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "com.typeit4me.clipping",
        "de.petermaurer.TransientPasteboardType",
        "Pasteboard generator type",
        "net.antelle.keeweb",
    ]

    public static func shouldIgnore(types: [String], text: String?, hasFiles: Bool) -> Bool {
        if types.contains(where: ignoredTypes.contains) { return true }
        if hasFiles { return false }
        guard let text else { return true }
        return text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }
}
